#include <stdlib.h>
#include <string.h>

long long* with_appended(const long long* values, int n, long long extra, int* returnSize) {
    long long* out = malloc(((size_t)n + 1) * sizeof *out);
    if (out == NULL) {
        *returnSize = 0;
        return NULL;
    }
    if (n > 0) {
        memcpy(out, values, (size_t)n * sizeof *out);
    }
    out[n] = extra;
    *returnSize = n + 1;
    return out;
}

