#include <stdlib.h>
#include <string.h>

char* take_prefix(const char* s, long long n) {
    size_t len = strlen(s);
    size_t take = (n <= 0) ? 0 : ((unsigned long long)n < len ? (size_t)n : len);
    char* out = malloc(take + 1);
    if (out == NULL) {
        return NULL;
    }
    memcpy(out, s, take);
    out[take] = '\0';
    return out;
}

