long long digits_value(const char* text) {
    if (text[0] == '\0') {
        return -1;
    }
    long long value = 0;
    for (size_t i = 0; text[i] != '\0'; i++) {
        if (text[i] < '0' || text[i] > '9') {
            return -1;
        }
        value = value * 10 + (text[i] - '0');
        if (value > 1000000000LL) {
            return -1;
        }
    }
    return value;
}

